def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    def count_score(seq):
        if not seq:
            return 0
        return sum(3 if a == 'C' and b == 'C' else 0 if a == 'C' and b == 'D' else 5 if a == 'D' and b == 'C' else 1 for a, b in seq)

    total_me = sum(1 for a, _ in history if a == 'C')
    total_op = sum(1 for _, b in history if b == 'C')
    my_coop_rate = total_me / n
    op_coop_rate = total_op / n

    # If far behind and few rounds left, defect more
    rounds_left = 100 - n

    # Opponent's recent behavior (last 10)
    recent = history[-10:] if n >= 10 else history
    recent_op_coop = sum(1 for _, b in recent if b == 'C') / len(recent)
    recent_me_coop = sum(1 for a, _ in recent if a == 'C') / len(recent)

    # Estimate opponent strategy type
    op_defects_after_my_defect = 0
    op_defects_after_my_coop = 0
    my_defect_count = 0
    my_coop_count = 0
    for i in range(1, n):
        prev_me = history[i-1][0]
        curr_op = history[i][1]
        if prev_me == 'D':
            my_defect_count += 1
            if curr_op == 'D':
                op_defects_after_my_defect += 1
        else:
            my_coop_count += 1
            if curr_op == 'D':
                op_defects_after_my_coop += 1

    # Detect always defect
    if n >= 5 and total_op == 0:
        return 'D' if rounds_left > 0 else 'C'

    # Detect always cooperate
    if n >= 5 and total_op == n:
        # Exploit but leave room for cooperation recovery
        if rounds_left > 5:
            return 'D'
        return 'C'

    # Detect tit-for-tat style: they mimic our previous action
    if n >= 6:
        mimic_count = sum(1 for i in range(1, n) if history[i][1] == history[i-1][0])
        if mimic_count >= n - 2:
            # We can either cooperate to get mutual C or defect to get 5 once
            # Play D occasionally to exploit; if they're forgiving, alternate
            if history[-1][1] == 'D':
                return 'C'
            else:
                # Try to defect for the bonus, but only if they seem not to retaliate hard
                if rounds_left > 2:
                    return 'D'
                return 'C'

    # Detect grim trigger: they cooperate until we defect, then always defect
    if n >= 4:
        i_defect = -1
        for i in range(n):
            if history[i][0] == 'D':
                i_defect = i
                break
        if i_defect >= 0:
            after_defect = history[i_defect+1:]
            if after_defect and all(b == 'D' for _, b in after_defect):
                return 'D'

    # Detect "always defect except first" or similar
    if n >= 3:
        if all(b == 'D' for _, b in history[1:]) and history[0][1] == 'C':
            return 'D'

    # Forgiveness-based strategy with occasional random exploration
    # If opponent is generally cooperative, cooperate
    if op_coop_rate > 0.7:
        # Mostly cooperate, occasional test defect
        if n % 7 == 0 and rounds_left > 5:
            return 'D'
        return 'C'

    # If opponent is mostly defecting, defect
    if op_coop_rate < 0.3:
        return 'D'

    # Mixed: use probability based on history
    # If we just played D and they played D, try to restore cooperation
    if n >= 1 and history[-1][0] == 'D' and history[-1][1] == 'D':
        return 'C'

    # If we played C and they played D, be more cautious
    if n >= 1 and history[-1][0] == 'C' and history[-1][1] == 'D':
        # Punish briefly then return to cooperation
        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'D':
            # They've defected twice, continue defecting
            return 'D'
        else:
            return 'D' if rounds_left > 10 else 'C'

    # If mutual cooperation, continue
    if n >= 1 and history[-1][0] == 'C' and history[-1][1] == 'C':
        # Occasionally defect to probe
        if n % 13 == 0 and rounds_left > 8:
            return 'D'
        return 'C'

    # Default: cooperate
    return 'C'
